Why does this Rust code fail to compile, and what is the idiomatic fix that keeps the same behaviour?

```rust
fn longest<'a>(items: &'a Vec<String>) -> &'a String {
    let mut best = &items[0];
    for it in items {
        if it.len() > best.len() { best = it; }
    }
    best
}

fn main() {
    let mut v = vec!["a".to_string(), "bbb".to_string()];
    let l = longest(&v);
    v.push("cc".to_string());
    println!("{}", l);
}
```

Find the concurrency bug in this C program, explain the exact interleaving that triggers it, and fix it.

```c
#include <pthread.h>
#include <stdio.h>

static int ready = 0;
static int payload = 0;

void *producer(void *arg) {
    payload = 42;
    ready = 1;
    return NULL;
}

void *consumer(void *arg) {
    while (!ready) { }
    printf("%d\n", payload);
    return NULL;
}

int main(void) {
    pthread_t p, c;
    pthread_create(&c, NULL, consumer, NULL);
    pthread_create(&p, NULL, producer, NULL);
    pthread_join(p, NULL);
    pthread_join(c, NULL);
    return 0;
}
```
